use vstd::prelude::*;

verus! {
    fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
        requires
            a.len() < 0x1_0000_0000, // Ensure the length of the vector is within bounds
        ensures
            result.len() == a.len() && 
            forall|i: nat| 0 <= i < a.len() ==> result[i] == a[i],
    {
        let mut result: Vec<T> = Vec::new();
        let mut idx: nat = 0;

        while idx < a.len() as nat
            invariant
                idx <= a.len() as nat,
                result.len() == idx,
                forall|j: nat| 0 <= j < idx ==> result[j] == a[j],
            decreases a.len() as nat - idx,
        {
            result.push(a[idx as usize]); // Copy the element from input to output
            idx = idx + 1;
        }

        result
    }
}
